import sys
sys.setrecursionlimit(2000000)

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    m = int(input_data[1])

    grid = []
    idx = 2
    for _ in range(n):
        grid.append(input_data[idx])
        idx += 1

    # Map characters to sequence indices: D->0, I->1, M->2, A->3
    char_to_idx = {'D': 0, 'I': 1, 'M': 2, 'A': 3}

    # dp[r][c] stores the max length of path ending at (r,c)
    # We will compute this using memoization with DFS
    # States: 0 = unvisited, 1 = visiting (cycle detection), 2 = visited

    state = [[0] * m for _ in range(n)]
    dp = [[0] * m for _ in range(n)]

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def dfs(r, c):
        if state[r][c] == 1:
            return float('inf')  # Cycle detected
        if state[r][c] == 2:
            return dp[r][c]

        state[r][c] = 1
        current_char = grid[r][c]
        current_seq = char_to_idx[current_char]
        next_seq = (current_seq + 1) % 4

        # Find next character needed
        target_chars = ['D', 'I', 'M', 'A']
        target = target_chars[next_seq]

        max_next = 0
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < m:
                if grid[nr][nc] == target:
                    res = dfs(nr, nc)
                    if res == float('inf'):
                        return float('inf')
                    max_next = max(max_next, res)

        dp[r][c] = 1 + max_next
        state[r][c] = 2
        return dp[r][c]

    max_path = 0
    has_cycle = False

    # Only start DFS from 'D' cells
    for r in range(n):
        for c in range(m):
            if grid[r][c] == 'D':
                if state[r][c] == 0:
                    res = dfs(r, c)
                    if res == float('inf'):
                        has_cycle = True
                    else:
                        max_path = max(max_path, res)

    if has_cycle:
        print("Poor Inna!")
    else:
        # The path length counts characters. Each DIMA is 4 characters.
        # Number of DIMAs = max_path // 4
        # But we need at least one full DIMA, which is 4 characters.
        # If max_path < 4, then 0 DIMAs.
        count = max_path // 4
        if count == 0:
            print("Poor Dima!")
        else:
            print(count)

if __name__ == "__main__":
    main()
